package checkout.pricing;

import java.math.BigDecimal;
import java.math.RoundingMode;

public final class DiscountPolicy {
    public static int totalCents(int unitCents, int quantity, boolean member) {
        if (unitCents < 0 || quantity < 0) {
            throw new IllegalArgumentException("unitCents and quantity must be nonnegative");
        }
        if (quantity == 0) {
            return 0;
        }

        BigDecimal total = BigDecimal.valueOf((long) unitCents).multiply(BigDecimal.valueOf((long) quantity));
        BigDecimal discountRate = BigDecimal.ZERO;
        if (member) {
            discountRate = discountRate.add(new BigDecimal("0.07"));
        }
        if (quantity >= 12) {
            discountRate = discountRate.add(new BigDecimal("0.05"));
        }

        if (discountRate.signum() > 0) {
            total = total.multiply(BigDecimal.ONE.subtract(discountRate));
        }

        total = total.setScale(0, RoundingMode.HALF_EVEN);
        try {
            return total.intValueExact();
        } catch (ArithmeticException ex) {
            throw new ArithmeticException("total exceeds Integer.MAX_VALUE");
        }
    }
}
